def main():
    assert set(P.keys()) == set(IDS), "id set mismatch"
    assert len(P) == 20, "count mismatch"
    os.makedirs(OUT, exist_ok=True)
    for cid in IDS:
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(P[cid], f, ensure_ascii=False, indent=2)
    cm = sum(1 for v in P.values() if v["trigger"]["changed_main"])
    ru = sum(1 for v in P.values() if v["trigger"]["reserve_used"])
    dp = sum(1 for v in P.values() if v["trigger"]["disputed"])
    print("written", len(P), "changed_main", cm, "reserve_used", ru, "disputed", dp)

if __name__ == "__main__":
    main()
